type Agent = { id: string; name?: string; provider?: string; [key: string]: unknown }
type AgentNode = { id: string; agent: string; prompt: string; gate: 'none' | 'approval'; type?: 'agent'; [key: string]: unknown }
type ValidateNode = { id: string; type: 'validate'; target: string; checks: Array<Record<string, unknown>>; on_fail: 'interrupt' | 'fail'; [key: string]: unknown }
type RenderNode = { id: string; type: 'render'; target: string; props_from: string; gate?: 'none' | 'approval'; [key: string]: unknown }
type Node = AgentNode | ValidateNode | RenderNode
type EdgeKind = 'default' | 'success' | 'warning' | 'error'
type Edge = [string, string] | { from: string; to: string; kind?: EdgeKind; label?: string }
type Workflow = { id: string; nodes: Node[]; edges: Edge[]; stop: Record<string, unknown>; [key: string]: unknown }
type Layout = Record<string, { x: number; y: number }>
type HistorySnapshot = { workflow: Workflow; layout: Layout }
type Log = RunEvent & { ts: string }
type RefError = { token: string; kind: 'missing'|'future' }
const isValidate = (node: Node): node is ValidateNode => node.type === 'validate'
const isRender = (node: Node): node is RenderNode => node.type === 'render'
const edgeFrom = (edge: Edge) => Array.isArray(edge) ? edge[0] : edge.from
const edgeTo = (edge: Edge) => Array.isArray(edge) ? edge[1] : edge.to
const edgeKind = (edge: Edge): EdgeKind => Array.isArray(edge) ? 'default' : edge.kind ?? 'default'
const edgeLabel = (edge: Edge) => Array.isArray(edge) ? '' : edge.label ?? ''
const PaletteContext = createContext<(agentId: string, type: 'agent'|'validate') => void>(() => undefined)
const edgeKey = (edge: Edge) => `${edgeFrom(edge)}→${edgeTo(edge)}`
const edgeColor = (kind: EdgeKind) => kind === 'success' ? 'var(--hub-success)' : kind === 'warning' ? 'var(--hub-warning)' : kind === 'error' ? 'var(--hub-error)' : 'var(--hub-edge-normal)'
// Must equal the node card's real rendered height (content is single-line/
// truncated throughout, so this is constant regardless of node type or text).
// A mismatch here desyncs edge endpoints, the arrow marker and addNode's drop
// offset from the actual DOM — which is exactly what made arrowheads land
// off the port before (a stale 126 vs the old card's real 107px).
// B2: 24px p-3 + 4 × 16px text-caption rows + 8px mt-2 + 2 × 4px mt-1
// + 2px borders. Measured on the rendered card: 105.1px.
const size = { width: 220, height: 105 }
const meta = (run: RunState) => run.metadata ?? {}
const nextId = (nodes: Node[]) => { let i = 1; const ids = new Set(nodes.map(node => node.id)); while (ids.has(`node-${i}`)) i++; return `node-${i}` }
const layoutFor = (nodes: Node[], saved: Layout): Layout => Object.fromEntries(nodes.map((node, i) => [node.id, saved[node.id] ?? { x: 70 + i * 260, y: 90 }]))
const snapshot = (workflow: Workflow, layout: Layout): HistorySnapshot => ({ workflow: JSON.parse(JSON.stringify(workflow)) as Workflow, layout: JSON.parse(JSON.stringify(layout)) as Layout })
function chain(workflow: Workflow) { const incoming = new Set(workflow.edges.map(edgeTo)); const byId = new Map(workflow.nodes.map(node => [node.id, node])); const start = workflow.nodes.find(node => !incoming.has(node.id)); if (!start) return workflow.nodes; const next = new Map(workflow.edges.map(edge => [edgeFrom(edge), edgeTo(edge)])); const result: Node[] = []; const seen = new Set<string>(); let current: Node | undefined = start; while (current && !seen.has(current.id)) { result.push(current); seen.add(current.id); current = byId.get(next.get(current.id) ?? '') } return result.length === workflow.nodes.length ? result : workflow.nodes }
