function scalar(value: unknown) { return typeof value === 'string' ? JSON.stringify(value) : JSON.stringify(value) }
function yaml(value: unknown, indent = 0): string[] { const pad = ' '.repeat(indent); if (Array.isArray(value)) return value.flatMap(item => item && typeof item === 'object' ? [`${pad}-`, ...yaml(item, indent + 2)] : [`${pad}- ${scalar(item)}`]); if (value && typeof value === 'object') return Object.entries(value as Record<string, unknown>).flatMap(([key, item]) => item && typeof item === 'object' ? [`${pad}${key}:`, ...yaml(item, indent + 2)] : [`${pad}${key}: ${scalar(item)}`]); return [`${pad}${scalar(value)}`] }
