  useEffect(() => { const onPointerDown = (event: PointerEvent) => { if (readOnly) return; const target = event.target as HTMLElement | null; if (target?.closest('[data-port]')) return; const card = target?.closest<HTMLElement>('[data-node-id]'); const node = selectedRef.current?.nodes.find(item => item.id === card?.dataset.nodeId); if (!node) return; if (event.shiftKey) { event.stopPropagation(); toggleSelected(node.id); return } if (!selectedIds.has(node.id)) return; const workflow = selectedRef.current; if (!workflow) return; event.stopPropagation(); const cursor = toWorldRef.current(event.clientX, event.clientY); drag.current = { ids: [...selectedIds], x: cursor.x, y: cursor.y, snapshot: snapshot(workflow, layoutRef.current) } }; window.addEventListener('pointerdown', onPointerDown, true); return () => window.removeEventListener('pointerdown', onPointerDown, true) }, [readOnly, selectedIds])
  // Fits the view to the current node bounds, matching a floor of 0.5 so labels
