  const deleteWorkflow = async () => { if (!selected) return; setPendingDelete(null); try { await api(`/api/workflows/${encodeURIComponent(selected.id)}`, { method: 'DELETE' }); setItems(rows => { const next = rows.filter(row => row.id !== selected.id); setSelected(next[0] ?? null); return next }); setNotice(t('workflows.deleted')) } catch (error) { setNotice(error instanceof ApiError ? error.message : t('workflows.deleteFailed')) } }

  if (!selected) return <div className="p-6 text-sm text-muted">{t('workflows.noValidWorkflow')}</div>
  const selectedEdge = selected.edges.find(item => edgeKey(item) === edge)
