function Palette({ agents, classes, query, setQuery }: { agents: Agent[]; classes: Record<string, { provider: string }>; query: string; setQuery: (value: string) => void }) { const onAdd = useContext(PaletteContext); const filtered = agents.filter(agent => `${agent.id} ${agent.name ?? ''}`.toLowerCase().includes(query.trim().toLowerCase())); return <section className="min-h-0 flex-1 overflow-y-auto p-3"><Input value={query} onChange={event => setQuery(event.target.value)} placeholder={t('workflows.searchAgents')} aria-label={t('workflows.searchAgents')} className="mb-3" /><div className="mb-2 text-section font-semibold uppercase tracking-[var(--hub-section-tracking)] text-muted">{t('workflows.paletteAgents')}</div>{filtered.length ? <div className="space-y-2">{filtered.map(agent => <button key={agent.id} type="button" draggable aria-label={t('workflows.addAgentAria', { id: agent.id })} onClick={() => onAdd(agent.id, 'agent')} onDragStart={event => { event.dataTransfer.setData('agent', agent.id); event.dataTransfer.effectAllowed = 'copy'; event.dataTransfer.setDragImage(event.currentTarget, 12, 12) }} className="flex w-full cursor-grab items-center gap-2 rounded-md border border-border-subtle bg-surface px-3 py-2 text-left text-xs active:cursor-grabbing"><ProviderDot provider={asProviderId(resolveProvider(agent.provider ?? '', classes))} /><span className="min-w-0"><span className="block truncate">{agent.name ?? agent.id}</span><span className="block truncate text-caption text-secondary">{agent.provider}</span></span></button>)}</div> : <EmptyState title={t('workflows.noAgentsMatch')} className="px-space-3 py-space-4" />}<div className="mb-2 mt-3 text-section font-semibold uppercase tracking-[var(--hub-section-tracking)] text-muted">{t('workflows.paletteNodes')}</div><button type="button" draggable onClick={() => onAdd('', 'validate')} onDragStart={event => { event.dataTransfer.setData('type', 'validate'); event.dataTransfer.effectAllowed = 'copy'; event.dataTransfer.setDragImage(event.currentTarget, 12, 12) }} className="flex w-full cursor-grab items-center gap-2 rounded-md border border-[var(--hub-node-validate)] bg-surface px-3 py-2 text-left text-xs text-[var(--hub-node-validate)] active:cursor-grabbing"><BadgeCheck size={16} strokeWidth={1.75} aria-hidden="true" />{t('workflows.validateNode')}</button></section> }

function Canvas({ workflow, layout, zoom, pan, activeId, selectedEdge, hoverEdge, draftEdge, references, state, classes, agents, editable, onSelect, onDrag, onEdgeSelect, onEdgeHover, onEdgeDelete, onEdgeStart, onConnect, onEdgeEnd, onNudge }: { workflow: Workflow; layout: Layout; zoom: number; pan: { x: number; y: number }; activeId: string | null; selectedEdge: string | null; hoverEdge: string | null; draftEdge: string |null; references: Map<string, RefError[]>; state: (id: string) => string; classes: Record<string, { provider: string }>; agents: Agent[]; editable: boolean; onSelect: (id: string) => void; onDrag: (value: { id: string; clientX: number; clientY: number; nodeX: number; nodeY: number }) => void; onEdgeSelect: (edge: string) => void; onEdgeHover: (edge: string | null) => void; onEdgeDelete: (edge: string) => void; onEdgeStart: (id: string) => void; onConnect: (from: string, to: string) => void; onEdgeEnd: () => void; onNudge: (id: string, dx: number, dy: number) => void }) {
  const activate = (event: React.KeyboardEvent, action: () => void) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); event.stopPropagation(); action() } }
  return <div className="absolute inset-0" style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`, transformOrigin: '0 0' }}><svg className="pointer-events-none absolute left-0 top-0 h-[1600px] w-[2400px] overflow-visible"><defs>{(['default', 'success', 'warning', 'error'] as EdgeKind[]).map(kind => <marker key={kind} id={`workflow-arrow-${kind}`} markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill={edgeColor(kind)} /></marker>)}</defs>{workflow.edges.map(item => { const from = edgeFrom(item), to = edgeTo(item), kind = edgeKind(item), label = edgeLabel(item); const a = layout[from], b = layout[to]; if (!a || !b) return null; const key = edgeKey(item); const x1 = a.x + size.width, y1 = a.y + size.height / 2, x2 = b.x, y2 = b.y + size.height / 2, cx = (x1 + x2) / 2, cy = (y1 + y2) / 2; const path = `M ${x1} ${y1} C ${cx} ${y1}, ${cx} ${y2}, ${x2} ${y2}`; const highlighted = key === selectedEdge || key === hoverEdge; const color = highlighted ? 'var(--hub-edge-selected)' : edgeColor(kind); return <g key={key}><path d={path} fill="none" stroke={color} strokeWidth={highlighted ? 3 : 2} markerEnd={`url(#workflow-arrow-${kind})`} />{label && <text x={cx} y={cy - 8} textAnchor="middle" fill={color} stroke="var(--hub-bg-app)" strokeWidth="4" paintOrder="stroke" className="text-caption">{label}</text>}<path d={path} fill="none" stroke="transparent" strokeWidth="14" role="button" tabIndex={0} aria-label={t('workflows.edgeAria', { from, to })} className="pointer-events-auto cursor-pointer focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent" onPointerDown={event => { event.stopPropagation(); onEdgeSelect(key) }} onDragEnter={event => { event.preventDefault(); onEdgeHover(key) }} onDragOver={event => { event.preventDefault(); onEdgeHover(key) }} onDragLeave={() => onEdgeHover(null)} onFocus={() => onEdgeSelect(key)} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onEdgeSelect(key) } else if (event.key === 'Delete' || event.key === 'Backspace') { event.preventDefault(); onEdgeDelete(key) } }} /></g> })}</svg>{workflow.nodes.map(node => { const p = layout[node.id] ?? { x: 40, y: 60 }; const status = state(node.id); const referenceErrors = references.get(node.id) ?? []; const agent = isValidate(node) || isRender(node) ? undefined : agents.find(item => item.id === node.agent); const provider = agent?.provider ? resolveProvider(agent.provider, classes) : t('common.notAvailable'); const inputCount = isValidate(node) || isRender(node) ? 0 : [...(node.prompt ?? '').matchAll(/\{\{(.*?)\}\}/g)].length; const gateApproval = isValidate(node) ? false : node.gate ? node.gate === 'approval' : isRender(node); const statusLabel = status === 'running' ? t('workflows.running') : status === 'done' ? t('workflows.complete') : status === 'fail' ? t('workflows.failed') : t('workflows.ready'); const nodeKeyDown = (event: React.KeyboardEvent) => { const step = event.shiftKey ? 20 : 10; const move = event.key === 'ArrowLeft' ? [-step, 0] : event.key === 'ArrowRight' ? [step, 0] : event.key === 'ArrowUp' ? [0, -step] : event.key === 'ArrowDown' ? [0, step] : null; if (move) { event.preventDefault(); onNudge(node.id, move[0], move[1]) } else activate(event, () => onSelect(node.id)) }; return <div key={node.id} data-node-id={node.id} role="button" tabIndex={0} aria-label={referenceErrors.length ? t('workflows.nodeInvalidAria', { id: node.id, count: referenceErrors.length }) : t('workflows.nodeAria', { id: node.id })} style={{ left: p.x, top: p.y, width: size.width }} onFocus={() => onSelect(node.id)} onKeyDown={nodeKeyDown} onPointerDown={event => { if ((event.target as HTMLElement).dataset.port) return; event.stopPropagation(); onDrag({ id: node.id, clientX: event.clientX, clientY: event.clientY, nodeX: p.x, nodeY: p.y }); onSelect(node.id) }} className={`group absolute select-none rounded-xl border bg-surface p-3 shadow-lg ${referenceErrors.length ? 'border-error' : activeId === node.id ? 'border-[var(--hub-accent)] ring-1 ring-[var(--hub-accent)]' : isValidate(node) ? 'border-[var(--hub-node-validate)]' : 'border-border-subtle'} ${status === 'running' ? 'node-pulse' : ''}`}><div className="flex h-4 items-center gap-1 text-caption"><span className="inline-flex items-center gap-1 truncate text-primary">{isValidate(node) ? <BadgeCheck size={14} strokeWidth={1.75} aria-hidden="true" /> : isRender(node) ? <Film size={14} strokeWidth={1.75} aria-hidden="true" /> : <Sparkles size={14} strokeWidth={1.75} aria-hidden="true" />}<span>{isValidate(node) ? t('workflows.nodeTypeValidate') : isRender(node) ? t('workflows.nodeTypeRender') : t('workflows.nodeTypeAgent')}</span></span><span className="ml-auto inline-flex items-center gap-1 text-muted">{status === 'done' ? <CheckCircle2 size={14} strokeWidth={1.75} aria-hidden="true" /> : status === 'fail' ? <CircleX size={14} strokeWidth={1.75} aria-hidden="true" /> : <Circle size={14} strokeWidth={1.75} aria-hidden="true" />}<span>{statusLabel}</span></span>{referenceErrors.length > 0 && <TriangleAlert size={14} strokeWidth={1.75} aria-label={t('workflows.invalidReferencesAria', { count: referenceErrors.length })} className="ml-1 shrink-0 text-error" />}</div><div className="mt-2 truncate font-mono text-caption font-semibold">{node.id}</div><div className="mt-1 truncate text-caption text-secondary">{isValidate(node) ? `${t('workflows.nodeTypeValidate')} · ${node.target || t('workflows.noTarget')}` : isRender(node) ? `${t('workflows.nodeTypeRender')} · ${node.target || t('workflows.noTarget')}` : `${node.agent} · ${provider}`}</div><div className="mt-1 flex h-4 items-center justify-between text-caption text-muted"><span>{t('workflows.inputsCount', { count: inputCount })}</span><span className={gateApproval ? 'text-warning' : ''}>{gateApproval ? t('workflows.approval') : t('workflows.noApproval')}</span></div>{editable && <IconButton data-port="right" icon={<span className="h-2 w-2 rounded-full bg-[var(--hub-edge-normal)]" />} onPointerDown={event => { event.stopPropagation(); onEdgeStart(node.id) }} onKeyDown={event => activate(event, () => onEdgeStart(node.id))} variant="handle" className={`absolute -right-3 top-1/2 -translate-y-1/2 border-0 bg-transparent p-2 opacity-0 group-hover:opacity-100 focus-visible:opacity-100 ${draftEdge ? 'opacity-100' : ''}`} aria-label={t('workflows.connectFrom', { id: node.id })} />}{editable && <IconButton data-port="left" icon={<span className="h-2 w-2 rounded-full bg-[var(--hub-edge-normal)]" />} onPointerUp={event => { event.stopPropagation(); if (draftEdge) onConnect(draftEdge, node.id); onEdgeEnd() }} onKeyDown={event => activate(event, () => { if (draftEdge) onConnect(draftEdge, node.id); onEdgeEnd() })} variant="handle" className={`absolute -left-3 top-1/2 -translate-y-1/2 border-0 bg-transparent p-2 opacity-0 group-hover:opacity-100 focus-visible:opacity-100 ${draftEdge ? 'opacity-100' : ''}`} aria-label={t('workflows.connectTo', { id: node.id })} />}</div> })}</div>
}

// Overview of the whole graph plus the slice of it currently on screen.
// Hidden under five nodes: below that the canvas already shows everything and
// the overlay would only cover it.
function Minimap({ layout, zoom, pan, canvasRef, onJump }: { layout: Layout; zoom: number; pan: { x: number; y: number }; canvasRef: React.RefObject<HTMLDivElement | null>; onJump: (pan: { x: number; y: number }) => void }) {
  const box = { width: 160, height: 110, pad: 8 }
  const positions = Object.entries(layout)
  const rect = canvasRef.current?.getBoundingClientRect()
  if (positions.length < 5 || !rect || !rect.width || !rect.height) return null
  const minX = Math.min(...positions.map(([, p]) => p.x)), minY = Math.min(...positions.map(([, p]) => p.y))
  const maxX = Math.max(...positions.map(([, p]) => p.x + size.width)), maxY = Math.max(...positions.map(([, p]) => p.y + size.height))
  // The viewport is part of the bounds: panning away from every node must still
  // show the frame moving instead of pinning it to an edge.
  const viewX = -pan.x / zoom, viewY = -pan.y / zoom, viewW = rect.width / zoom, viewH = rect.height / zoom
  const left = Math.min(minX, viewX), top = Math.min(minY, viewY)
  const right = Math.max(maxX, viewX + viewW), bottom = Math.max(maxY, viewY + viewH)
  const scale = Math.min((box.width - box.pad * 2) / (right - left), (box.height - box.pad * 2) / (bottom - top))
  const toBox = (x: number, y: number) => ({ x: box.pad + (x - left) * scale, y: box.pad + (y - top) * scale })
  const centreOn = (event: React.PointerEvent<HTMLDivElement>) => {
    const own = event.currentTarget.getBoundingClientRect()
    const world = { x: left + (event.clientX - own.left - box.pad) / scale, y: top + (event.clientY - own.top - box.pad) / scale }
    onJump({ x: Math.round(rect.width / 2 - world.x * zoom), y: Math.round(rect.height / 2 - world.y * zoom) })
  }
  const frame = toBox(viewX, viewY)
  return <div role="presentation" onPointerDown={centreOn} onPointerMove={event => { if (event.buttons === 1) centreOn(event) }} style={{ width: box.width, height: box.height }} className="absolute bottom-3 right-3 cursor-pointer rounded-md border border-border-subtle bg-app/80 backdrop-blur-sm">
    {positions.map(([id, p]) => { const at = toBox(p.x, p.y); return <span key={id} className="absolute rounded-[2px] bg-[var(--hub-node-agent)]" style={{ left: at.x, top: at.y, width: Math.max(2, size.width * scale), height: Math.max(2, size.height * scale) }} /> })}
    <span className="absolute rounded-[2px] border border-[var(--hub-accent)]" style={{ left: frame.x, top: frame.y, width: Math.max(4, viewW * scale), height: Math.max(4, viewH * scale) }} />
  </div>
}

