function Overview({ readOnly, node, prior, agents, checksText, setChecksText, setChecksError, checksError, change, update: _update, errors }: { readOnly: boolean; node: Node; prior: Node[]; agents: Agent[]; checksText: string; setChecksText: (value: string) => void; setChecksError: (value: string) => void; checksError: string; change: (field: string, value: unknown) => void; update: (fn: (workflow: Workflow) => Workflow) => void; errors: RefError[] }) { const promptRef = useRef<HTMLTextAreaElement>(null); const [query, setQuery] = useState<string | null>(null); const [selectedVariable, setSelectedVariable] = useState(0); const prompt = isValidate(node) || isRender(node) ? '' : node.prompt; const variables = ['{{objective}}', '{{inputs}}', ...prior.flatMap(item => [`{{${item.id}_output}}`, `{{${item.id}_claims}}`])]; const suggestions = query === null ? [] : variables.filter(variable => variable.slice(2, -2).toLowerCase().includes(query.toLowerCase())); const updatePrompt = (value: string, cursor: number) => { change('prompt', value); const match = value.slice(0, cursor).match(/\{\{([^{}]*)$/); setQuery(match ? match[1] : null); setSelectedVariable(0) }; const insertVariable = (variable: string) => { const textarea = promptRef.current; const cursor = textarea?.selectionStart ?? prompt.length; const start = query === null ? cursor : cursor - query.length - 2; const value = `${prompt.slice(0, start)}${variable}${prompt.slice(cursor)}`; change('prompt', value); setQuery(null); requestAnimationFrame(() => { textarea?.focus(); textarea?.setSelectionRange(start + variable.length, start + variable.length) }) }; const promptKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => { if (query === null) return; if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); setSelectedVariable(current => suggestions.length ? (current + (event.key === 'ArrowDown' ? 1 : suggestions.length - 1)) % suggestions.length : 0) } else if (event.key === 'Enter' && suggestions[selectedVariable]) { event.preventDefault(); insertVariable(suggestions[selectedVariable]) } else if (event.key === 'Escape') { event.preventDefault(); setQuery(null) } }; return <>{isValidate(node) ? <><label className="mb-3 block text-caption text-muted">target<Select disabled={readOnly} value={node.target} onChange={event => change('target', event.target.value)}><option value="">{t('workflows.selectPriorNode')}</option>{prior.map(item => <option key={item.id} value={item.id}>{item.id}</option>)}</Select></label><label className="mb-3 block text-caption text-muted">on_fail<Select disabled={readOnly} value={node.on_fail} onChange={event => change('on_fail', event.target.value)}><option value="interrupt">interrupt</option><option value="fail">fail</option></Select></label><label className="block text-caption text-muted">checks JSON<Textarea disabled={readOnly} value={checksText} onChange={event => { setChecksText(event.target.value); try { const value = JSON.parse(event.target.value); if (!Array.isArray(value)) throw new Error(); setChecksError(''); change('checks', value) } catch { setChecksError(t('workflows.invalidJson')) } }} rows={8} />{checksError && <span className="text-error">{checksError}</span>}</label></> : isRender(node) ? <><div className="mb-3"><div className="text-caption text-muted">target</div><div className="text-caption text-primary">{node.target}</div></div><label className="mb-3 block text-caption text-muted">props_from<Select disabled={readOnly} value={node.props_from} onChange={event => change('props_from', event.target.value)}><option value="">{t('workflows.selectPriorNode')}</option>{prior.map(item => <option key={item.id} value={item.id}>{item.id}</option>)}</Select></label><label className="block text-caption text-muted">gate<Select disabled={readOnly} value={node.gate ?? 'approval'} onChange={event => change('gate', event.target.value)}><option value="none">{t('workflows.none')}</option><option value="approval">{t('workflows.requiresApproval')}</option></Select></label></> : <><label className="mb-3 block text-caption text-muted">{t('workflows.agentField')}<Select disabled={readOnly} value={node.agent} onChange={event => change('agent', event.target.value)}>{agents.map(agent => <option key={agent.id} value={agent.id}>{agent.id}</option>)}</Select></label><label className="mb-3 block text-caption text-muted">{t('workflows.executionPolicy')}<Select disabled={readOnly} value={node.gate} onChange={event => change('gate', event.target.value)}><option value="none">{t('workflows.none')}</option><option value="approval">{t('workflows.requiresApproval')}</option></Select></label><label className="block text-caption text-muted">{t('workflows.prompt')}<Textarea ref={promptRef} disabled={readOnly} value={prompt} onChange={event => updatePrompt(event.target.value, event.target.selectionStart)} onKeyDown={promptKeyDown} rows={8} aria-autocomplete="list" aria-controls="workflow-variable-suggestions" aria-expanded={query !== null} /></label><div className="mt-2"><div className="mb-1 text-caption text-muted">{t('workflows.availableVariables')}</div><div className="flex flex-wrap gap-1">{variables.map(variable => <button key={variable} type="button" disabled={readOnly} onClick={() => insertVariable(variable)} className="rounded border border-border-subtle bg-surface px-2 py-1 font-mono text-caption text-secondary disabled:cursor-not-allowed disabled:opacity-60">{variable}</button>)}</div></div>{query !== null && <div id="workflow-variable-suggestions" role="listbox" className="mt-2 rounded-md border border-border-subtle bg-surface p-1">{suggestions.length ? suggestions.map((variable, index) => <button key={variable} type="button" role="option" aria-selected={selectedVariable === index} onMouseDown={event => event.preventDefault()} onClick={() => insertVariable(variable)} className={`block w-full rounded px-2 py-1 text-left font-mono text-caption ${selectedVariable === index ? 'bg-[var(--hub-accent)] text-white' : 'text-secondary'}`}>{variable}</button>) : <span className="block px-2 py-1 text-caption text-muted">{t('workflows.noMatchingVariables')}</span>}</div>}</>}{errors.length > 0 && (isValidate(node) || isRender(node) ? <div className="mt-3 rounded-md border border-error bg-error-subtle p-2 text-caption text-error">{t('workflows.invalidReference', { errors: errors.map(error => error.token).join(', ') })}</div> : <div className="mt-3 space-y-1 rounded-md border border-error bg-error-subtle p-2 text-caption text-error">{errors.map(error => <div key={`${error.kind}-${error.token}`}>{error.kind === 'missing' ? t('workflows.invalidReferenceMissing', { token: `{{${error.token}}}` }) : t('workflows.invalidReferenceFuture', { token: `{{${error.token}}}` })}</div>)}</div>)}</> }
